import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";
import { writeFileSync } from "node:fs";
import { computeDiagnostic as original } from "@/engines/diagnostic/computeDiagnostic";
import { computeDiagnostic as candidate } from "physiology:diagnostic-candidate";
import { predictRunMLSSPctFromVLaCE } from "@/lib/v2/runMLSSPredictor";
import { QA_PROFILES } from "@/lib/plan/qa/syntheticProfiles";
import { buildPilotDiagnosticInput } from "@/lib/plan/qa/preparePilotTrainingPlanContext";

beforeEach(() => {
  vi.useFakeTimers({ toFake: ["Date"] });
  vi.setSystemTime(new Date("2026-10-29T14:00:00Z"));
  vi.stubGlobal("fetch", () => { throw Error("NETWORK_FORBIDDEN"); });
  vi.spyOn(console, "log").mockImplementation(() => {});
  vi.spyOn(console, "warn").mockImplementation(() => {});
});
afterEach(() => { vi.useRealTimers(); vi.restoreAllMocks(); vi.unstubAllGlobals(); });
const seed = buildPilotDiagnosticInput(QA_PROFILES.find(p => p.id === "B-MARATHON")!);
const input = { ...seed, runEconomyScore: 65, vlamaxRun: 0.5, vma: 18, paceThresholdSecPerKm: null };
const compute = process.env.PHYSIOLOGY_BASELINE === "1" ? original : candidate;

describe("F4 — economy score is distinct from oxygen cost", () => {
  it("does not synthesize MLSS from a 0–100 score when CE is missing", () => {
    expect(compute(input).runMLSS?.prediction ?? null).toBeNull();
  });
  it("uses explicit CE in ml O2/kg/km, preserving the original limiter score", () => {
    const enriched = { ...input, runningEconomyCostMlKgKm: 200 };
    const before = original(enriched);
    const after = compute(enriched);
    expect(after.runMLSS?.prediction).toEqual(predictRunMLSSPctFromVLaCE(0.5, 200));
    expect(after.limiter).toEqual(before.limiter);
    expect(after.effectifs).toEqual(before.effectifs);
    expect(after._rawInput.runEconomyScore).toBe(65);
    if (process.env.PHYSIOLOGY_WRITE_EVIDENCE === "1") {
      writeFileSync("docs/physiology-validation/v1/evidence/economy-contract.json", JSON.stringify({
        syntheticOnly: true, input: enriched, before: before.runMLSS, after: after.runMLSS,
        limitersUnchanged: JSON.stringify(before.limiter) === JSON.stringify(after.limiter),
        scope: "experimental in-memory patch; no production source edited; CE has no new automatic producer",
      }, null, 2) + "\n");
    }
  });
  it("retains threshold/VMA proxy when CE is absent, without false model cross-validation", () => {
    const after = compute({ ...input, paceThresholdSecPerKm: 240 });
    expect(after.runMLSS?.effectiveSource).toBe("observed");
    expect(after.runMLSS?.effectivePct).toBeCloseTo(83.3, 1);
    expect(after.runMLSS?.crossValidation).toBeNull();
  });
  it.each(QA_PROFILES.map(profile => [profile.id, profile] as const))(
    "preserves effectifs, limiter, readiness and targets for existing synthetic profile %s", (_id, profile) => {
      const raw = buildPilotDiagnosticInput(profile);
      const before = original(raw);
      const after = candidate(raw);
      expect(after.effectifs).toEqual(before.effectifs);
      expect(after.limiter).toEqual(before.limiter);
      expect(after.readiness).toEqual(before.readiness);
      expect(after.targets).toEqual(before.targets);
      if (raw.sportFocus === "bike") expect(after.runMLSS).toBeNull();
    },
  );
});

import { defineConfig } from "vitest/config";
import base from "../../../vitest.config";
import { readFileSync } from "node:fs";
import path from "node:path";

const candidateId = path.resolve("experimental/physiology-validation/v1/diagnostic-candidate.ts");

export default defineConfig({
  ...base,
  plugins: [...base.plugins, {
    name: "physiology-review-only-diagnostic-candidate",
    resolveId(id) { if (id === "physiology:diagnostic-candidate") return candidateId; },
    load(id) {
      if (id !== candidateId) return;
      const source = readFileSync("src/engines/diagnostic/computeDiagnostic.ts", "utf8");
      const start = source.indexOf("function computeRunMLSSFromInput(");
      const end = source.indexOf("function computeSynthesis(", start);
      const prefix = source.slice(0, start);
      // Match the two CE arguments only, never the score used by limiter/readiness.
      const body = source.slice(start, end).replace(/input\.runEconomyScore/g, "input.runningEconomyCostMlKgKm");
      if (start < 0 || end < 0 || (source.slice(start, end).match(/input\.runEconomyScore/g) ?? []).length !== 2) {
        throw new Error("Review patch no longer matches the two MLSS CE arguments");
      }
      return (prefix + body + source.slice(end))
        .replaceAll('from "./types"', 'from "@/engines/diagnostic/types"')
        .replaceAll('from "./raceTimeEstimator"', 'from "@/engines/diagnostic/raceTimeEstimator"');
    },
  }],
  test: { ...base.test, include: ["experimental/physiology-validation/v1/**/*.test.ts"], retry: 0 },
});

import { canGuidePrescription } from "@/lib/limiterPrescription";
/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * TFCL DIAGNOSTIC ENGINE™ — Orchestrateur
 * 
 * Point d'entrée unique : computeDiagnostic(input) → AthleteDiagnostic
 * 
 * Appelle les sous-modules existants dans l'ordre :
 * 1. Effectifs (VLamax, TTE, Fatigue)
 * 2. Limiteur Unifié (ex-Compas)
 * 3. Potentiel Physiologique
 * 4. Cibles Physiologiques
 * 5. Risque Blessure
 * 6. Synthèse
 *
 * Le Decision Reliability Engine (DRE) n'est PAS calculé ici : il est
 * produit séparément par la couche d'affichage (Dashboard, PDF Race
 * Simulation) via computeFullDRE, avec les vraies confidences du snapshot
 * actif. Un champ reliability figurait autrefois ici, toujours à null et
 * jamais lu par aucun consommateur de computeDiagnostic() — supprimé
 * (audit "estimations physiologiques", Cluster 3, finding secondaire).
 * ═══════════════════════════════════════════════════════════════════════════════
 */

import type {
  DiagnosticInput,
  AthleteDiagnostic,
  DiagnosticSynthesis,
  DiagnosticAlert,
} from "./types";
import { DIAGNOSTIC_ENGINE_VERSION, DIAGNOSTIC_ENGINE_DISCLAIMER } from "./types";

// Sub-engines (unchanged — they remain the computation core)
import { computeVLamaxEffectif, type VLamaxEffectif } from "@/lib/vlamaxEffectif";
import { computeTTEEffectif, type TTEEffectif } from "@/lib/tteEffectif";
import { computeFatigueEffectif, type FatigueEffectif } from "@/lib/fatigueEffectif";
import { detectUnifiedLimiter, LIMITER_INFO, type UnifiedLimiterResult } from "@/lib/v2/unifiedLimiterDetection";
import { computeDecisionTFCL, type PotentielV2Result } from "@/lib/v2/potentielTypes";
import { getTargetsForAmbition, normalizeObjective, getVLamaxRange } from "@/lib/physiologicalTargets";

// Forme locale du "compass" attendu par computeDecisionTFCL (ComputeDecisionTFCLInput.compass).
// Anciennement importée de compassScoring.ts — ce moteur (compassScoring.ts) a été retiré
// car il n'avait plus aucun autre consommateur dans l'app (cf. Cluster 2, nettoyage) ; sa
// logique de gap-analysis ci-dessous lui était de toute façon indépendante.
interface CompassAxisScore {
  score: number;
  rawScore: number;
  label: string;
  explanation: string;
  formula: string;
  inputs: Record<string, number | string | null>;
  confidence: number;
  source: string;
}

interface CompassScores {
  capaciteAerobie: CompassAxisScore;
  toleranceEffort: CompassAxisScore;
  profilMetabolique: CompassAxisScore;
  robustesse: CompassAxisScore;
  globalScore: number;
  globalLabel: string;
  globalColor: "success" | "warning" | "destructive";
  dataCompleteness: number;
  mainLimitation: string | null;
  mainStrength: string | null;
  isFatigueModulated: boolean;
}
import { computeRunInjuryRisk, type RunInjuryRiskEnvelope } from "@/lib/runInjuryRisk";
import { computeBikeInjuryRisk, type InjuryRiskEnvelope } from "@/lib/v2/injuryRiskUnified";
import { fatigueStateToScore } from "@/lib/fatigueStateMapping";
import {
  predictRunMLSSPctFromVLaCE,
  crossValidateRunMLSS,
  type RunMLSSPrediction,
  type RunMLSSCrossValidation,
} from "@/lib/v2/runMLSSPredictor";
import { estimateFromRaceChronos } from "./raceTimeEstimator";

// ═══════════════════════════════════════════════════════════════════════════════
// ORCHESTRATEUR PRINCIPAL
// ═══════════════════════════════════════════════════════════════════════════════

export function computeDiagnostic(input: DiagnosticInput): AthleteDiagnostic {
  // ── 1. Indices Effectifs ──────────────────────────────────────────────────
  const vlamax = computeVLamaxFromInput(input);
  const tte = computeTTEFromInput(input);
  const fatigue = computeFatigueFromInput(input, tte, vlamax);

  // ── 2. Limiteur Unifié ────────────────────────────────────────────────────
  const limiter = detectUnifiedLimiter({
    vo2max: input.vo2max,
    ftpKg: input.ftpKg,
    vlamax: vlamax.value,
    wprimeKj: input.wprimeKj,
    cpDataQuality: input.cpDataQuality,
    tte: tte.tte_min,
    fatmax: input.fatmax,
    economyScore: input.runEconomyScore,
    availabilityScore: fatigue.score < 30 ? 85 : fatigue.score < 55 ? 60 : fatigue.score < 75 ? 35 : 15,
    hasHealthAlerts: input.checkinData?.painFlag ?? false,
    objectif: input.objectif,
    ambition: input.ambition,
    age: input.age,
    vma: input.vma,
    sportFocus: input.sportFocus,
    targetRaceDurationMin: input.targetRaceDurationMin ?? null,
  });

  // ── 3. Potentiel Physiologique ─────────────────────────────────────────────────────
  const readiness = computeReadinessFromInput(input, limiter);

  // ── 4. Cibles Physiologiques ──────────────────────────────────────────────
  const normalized = normalizeObjective(input.objectif);
  const vlamaxRange = getVLamaxRange(input.objectif, input.ambition, input.sportFocus);
  const currentTargets = {
    ...getTargetsForAmbition(normalized, input.ambition),
    vlamax: vlamaxRange,
  };

  // ── 5. Risque Blessure ────────────────────────────────────────────────────
  const runInjuryRisk = computeRunInjuryRiskFromInput(input, fatigue, tte, vlamax);
  const bikeInjuryRisk = computeBikeInjuryRiskFromInput(input, fatigue, tte, vlamax);

  // ── 6bis. Run MLSS (Modèle C — cross-validator silencieux + fallback) ──
  const runMLSS = computeRunMLSSFromInput(input);

  // ── 6ter. Race Chrono Estimate (RAW — Riegel/VDOT/ACSM/durabilité) ──
  // Calculé seulement si des chronos sont saisis. Sortie tagguée "race_chrono".
  const raceChronoEstimate = input.raceChronos
    ? estimateFromRaceChronos(input.raceChronos)
    : null;

  // ── 7. Synthèse ───────────────────────────────────────────────────────────
  const synthesis = computeSynthesis(limiter, readiness, fatigue, runInjuryRisk, input, runMLSS);

  // ── 8. Métadonnées ────────────────────────────────────────────────────────
  const confidenceGlobal = Math.min(
    vlamax.confidence,
    tte.confidence,
    fatigue.confidence,
    limiter.confidence
  );

  const dataCompleteness = computeDataCompleteness(input);

  return {
    athleteId: input.athleteId,
    objectif: input.objectif,
    ambition: input.ambition,
    sportFocus: input.sportFocus,
    effectifs: { vlamax, tte, fatigue },
    limiter,
    readiness,
    targets: {
      current: currentTargets,
      vlamaxRange,
      adjustedForAge: input.age !== null && input.age >= 40,
    },
    injuryRisk: {
      run: runInjuryRisk,
      bike: bikeInjuryRisk,
    },
    runMLSS,
    raceChronoEstimate,
    synthesis,
    _rawInput: input,
    meta: {
      timestamp: new Date().toISOString(),
      version: DIAGNOSTIC_ENGINE_VERSION,
      confidenceGlobal,
      dataCompleteness,
      disclaimer: DIAGNOSTIC_ENGINE_DISCLAIMER,
    },
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// SOUS-FONCTIONS D'ADAPTATION (bridge ancien → nouveau)
// ═══════════════════════════════════════════════════════════════════════════════

function computeVLamaxFromInput(input: DiagnosticInput): VLamaxEffectif {
  // ✅ COHÉRENCE GLOBALE : si un VLamax effectif a déjà été calculé en amont
  // (typiquement Index.tsx avec l'historique complet tests+snapshots), on le
  // réutilise tel quel pour garantir une valeur identique partout dans l'app.
  if (input.vlamaxEffectifPrecomputed) {
    return input.vlamaxEffectifPrecomputed;
  }
  // ✅ VLamax adaptée à l'objectif : pour un coureur pur, on doit passer
  // vlamax_run au moteur V2 ; sinon il interprète la VLamax vélo comme
  // VLamax CAP et produit un profil incohérent.
  const isRunFocus = input.sportFocus === "run";
  const snapshotObj = {
    id: "diagnostic-snapshot",
    athlete_id: input.athleteId,
    date: new Date().toISOString().split("T")[0],
    vlamax: input.vlamax,
    vlamax_run: input.vlamaxRun,
    ftp: input.ftp,
    pmax_5s: input.pmax5s,
    weight_kg: input.weightKg,
    sport_main: isRunFocus ? "run" : "bike",
    p30s_w: input.p30sW,
    p60s_w: input.p60sW,
    map5min_w: input.map5minW,
    tte_observed_min: input.tteObservedMin,
    protocol_quality: input.protocolQuality,
    objectif: input.objectif,
    vo2max: input.vo2max,
    vma: input.vma,
    pace_threshold_sec_per_km: input.paceThresholdSecPerKm,
    running_power_threshold: input.runningPowerThreshold,
    running_power_1s: input.runningPower1s,
    running_power_5s: input.runningPower5s,
    running_power_30s: input.runningPower30s,
    running_power_60s: input.runningPower60s,
    running_power_5min: input.runningPower5min,
    sprint_15s_distance: input.sprint15sDistance,
    css: input.css,
    vlamax_source: input.vlamaxSource,
    vlamax_protocol: input.vlamaxProtocol,
    vlamax_is_reference: input.vlamaxIsReference,
  };

  return computeVLamaxEffectif({
    athleteId: input.athleteId,
    objectif: input.objectif,
    activeSnapshotId: "diagnostic-snapshot",
    tests: [],
    snapshots: [snapshotObj],
  });
}

function computeTTEFromInput(input: DiagnosticInput): TTEEffectif {
  // ✅ COHÉRENCE GLOBALE (mirroir de computeVLamaxFromInput) : si un TTE
  // effectif a déjà été calculé en amont, on le réutilise tel quel pour
  // garantir une valeur identique partout dans l'app plutôt que de le
  // re-dériver depuis des champs bruts potentiellement incomplets.
  if (input.tteEffectifPrecomputed) {
    return input.tteEffectifPrecomputed;
  }
  // Sport-aware : on relaie sportFocus et le champ TTE run dédié pour éviter
  // qu'un coureur retombe silencieusement sur tte_observed_min (bike).
  const sport: "bike" | "run" =
    input.sportFocus === "run" ? "run" : "bike";
  return computeTTEEffectif({
    ftp: input.ftp,
    tss_7d: input.tss7d,
    tte_mode: input.tteMode,
    tte_observed_min: input.tteObservedMin,
    tte_observed_min_run: input.tteObservedMinRun ?? null,
    tte_proxy_min_run: input.tteProxyMinRun ?? null,
    tte_proxy_confidence: input.tteProxyConfidence ?? null,
    tte_proxy_label: input.tteProxyLabel ?? null,
    sport,
    objectif: input.objectif,
    age: input.age, // F33: ajustement masters
  });
}

function computeFatigueFromInput(
  input: DiagnosticInput,
  tte: TTEEffectif,
  vlamax: VLamaxEffectif
): FatigueEffectif {
  const fatiguePercue = fatigueStateToScore(input.fatigueState);

  return computeFatigueEffectif({
    tss7d: input.tss7d,
    fatiguePercue,
    tteEffectif: tte,
    vlamaxEffectif: vlamax,
    age: input.age,
    objectif: input.objectif,
  });
}

function buildAxisScore(score: number, label: string, explanation: string): CompassAxisScore {
  return {
    score,
    rawScore: score,
    label,
    explanation,
    formula: "derived from gap analysis",
    inputs: {},
    confidence: 0.7,
    source: "diagnostic_engine",
  };
}

function computeReadinessFromInput(
  input: DiagnosticInput,
  limiter: UnifiedLimiterResult
): PotentielV2Result {
  // Build compass scores from limiter gap analysis
  let aerobicScore = 50;
  let toleranceScore = 50;
  let metabolicScore = 50;
  let robustnessScore = 50;

  for (const gap of limiter.gapAnalysis) {
    if (!canGuidePrescription(gap)) continue;
    if (gap.metric === "VO2max" || gap.metric === "FTP/kg" || gap.metric === "VMA") {
      const score = Math.max(0, Math.min(100, 100 + gap.gapPercent));
      aerobicScore = Math.min(aerobicScore === 50 ? score : aerobicScore, score);
    } else if (gap.metric === "VLamax") {
      // VLamax : plus bas est mieux (profil endurance), donc gapPercent positif signifie
      // une VLamax AU-DESSUS de la cible optimale = mauvais — l'inverse de la convention
      // des autres métriques (VO2max/FTP/VMA/TTE), où gapPercent positif = au-dessus de
      // la cible = bon. Le signe doit être inversé pour rester cohérent avec l'échelle 0-100.
      metabolicScore = Math.max(0, Math.min(100, 100 - gap.gapPercent));
    } else if (gap.metric === "TTE") {
      toleranceScore = Math.max(0, Math.min(100, 100 + gap.gapPercent));
    } else if (gap.metric === "Économie" || gap.metric === "W' (kJ)") {
      const score = Math.max(0, Math.min(100, 100 + gap.gapPercent));
      robustnessScore = Math.min(robustnessScore === 50 ? score : robustnessScore, score);
    }
  }

  const globalScore = Math.round(
    aerobicScore * 0.20 + toleranceScore * 0.30 + metabolicScore * 0.25 + robustnessScore * 0.25
  );

  const compassScores: CompassScores = {
    capaciteAerobie: buildAxisScore(aerobicScore, "Capacité Aérobie", "Score dérivé du gap analysis"),
    toleranceEffort: buildAxisScore(toleranceScore, "Tolérance à l'Effort", "Score dérivé du gap analysis"),
    profilMetabolique: buildAxisScore(metabolicScore, "Profil Métabolique", "Score dérivé du gap analysis"),
    robustesse: buildAxisScore(robustnessScore, "Robustesse", "Score dérivé du gap analysis"),
    globalScore,
    globalLabel: globalScore >= 80 ? "Profil Optimal" : globalScore >= 65 ? "Bon Équilibre" : globalScore >= 50 ? "En Progression" : "À Développer",
    globalColor: globalScore >= 65 ? "success" : globalScore >= 50 ? "warning" : "destructive",
    dataCompleteness: Math.round(computeDataCompleteness(input) * 100),
    mainLimitation: limiter.limiterLabel !== "Profil équilibré" ? limiter.limiterLabel : null,
    mainStrength: null,
    isFatigueModulated: false,
  };

  return computeDecisionTFCL({
    compass: compassScores,
    guardrails: {
      healthAlert: input.checkinData?.painFlag,
      dataCompleteness: computeDataCompleteness(input),
    },
  });
}

function computeRunInjuryRiskFromInput(
  input: DiagnosticInput,
  fatigue: FatigueEffectif,
  tte: TTEEffectif,
  vlamax: VLamaxEffectif
): RunInjuryRiskEnvelope | null {
  if (input.sportFocus === "bike") return null;

  return computeRunInjuryRisk({
    fatigueEffectif: fatigue,
    vlamaxEffectif: vlamax,
    tteEffectif: tte,
    tss7d: input.tss7d,
    age: input.age,
    objectif: input.objectif,
  });
}

function computeBikeInjuryRiskFromInput(
  input: DiagnosticInput,
  fatigue: FatigueEffectif,
  tte: TTEEffectif,
  vlamax: VLamaxEffectif
): InjuryRiskEnvelope | null {
  if (input.sportFocus === "run") return null;

  return computeBikeInjuryRisk({
    vlamaxValue: vlamax.value,
    // ifscScore / longRideDurationMin : non disponibles dans le Diagnostic
    // Engine (IFSC nécessite la cadence spontanée, calculé séparément côté
    // Dashboard). Traités comme "inconnu" par computeBikeInjuryRisk — même
    // fallback que le Dashboard leur applique déjà (runLoad7d/longRide
    // toujours null là-bas aussi, "pas encore disponible").
    ifscScore: null,
    longRideDurationMin: null,
    tteMin: tte.tte_min,
    fatiguePct: fatigue.score,
    tss7d: input.tss7d,
    age: input.age,
    objectif: input.objectif,
  });
}

// ─── Run MLSS (Modèle C) ────────────────────────────────────────────────
function computeRunMLSSFromInput(
  input: DiagnosticInput
): AthleteDiagnostic["runMLSS"] {
  if (input.sportFocus === "bike") return null;

  // 1. Observed MLSS_pct from pace_threshold + VMA
  //    speed_threshold_kmh = 3600 / pace_sec_per_km
  //    MLSS_pct ≈ (speed_threshold / VMA) × 100  (proxy %vVO2max ≈ %VO2max au seuil)
  let observedPct: number | null = null;
  if (
    input.paceThresholdSecPerKm != null &&
    input.paceThresholdSecPerKm > 0 &&
    input.vma != null &&
    input.vma > 0
  ) {
    const speedKmh = 3600 / input.paceThresholdSecPerKm;
    const ratio = (speedKmh / input.vma) * 100;
    if (ratio >= 50 && ratio <= 100) {
      observedPct = Number(ratio.toFixed(1));
    }
  }

  // 2. Predicted MLSS_pct via Modèle C (VLamax run + CE)
  const prediction = predictRunMLSSPctFromVLaCE(
    input.vlamaxRun,
    input.runEconomyScore
  );

  // 3. Cross-validation
  const crossValidation =
    observedPct !== null && prediction
      ? crossValidateRunMLSS(observedPct, input.vlamaxRun, input.runEconomyScore)
      : null;

  // 4. Effective value (observed wins, predicted as fallback)
  let effectivePct: number | null = null;
  let effectiveSource: "observed" | "predicted" | "none" = "none";
  if (observedPct !== null) {
    effectivePct = observedPct;
    effectiveSource = "observed";
  } else if (prediction) {
    effectivePct = prediction.mlssPct;
    effectiveSource = "predicted";
  }

  if (observedPct === null && prediction === null) return null;

  return {
    observedPct,
    prediction,
    crossValidation,
    effectivePct,
    effectiveSource,
  };
}

// ═══════════════════════════════════════════════════════════════════════════════
// SYNTHÈSE
// ═══════════════════════════════════════════════════════════════════════════════

function computeSynthesis(
  limiter: UnifiedLimiterResult,
  readiness: PotentielV2Result,
  fatigue: FatigueEffectif,
  runInjuryRisk: RunInjuryRiskEnvelope | null,
  input: DiagnosticInput,
  runMLSS: AthleteDiagnostic["runMLSS"]
): DiagnosticSynthesis {
  const alerts: DiagnosticAlert[] = [];

  // Alertes fatigue
  if (fatigue.score > 75) {
    alerts.push({
      severity: "critical",
      message: `Fatigue critique (${fatigue.score}%) — limiter l'intensité`,
      source: "fatigue",
    });
  } else if (fatigue.score > 55) {
    alerts.push({
      severity: "warning",
      message: `Fatigue élevée (${fatigue.score}%) — privilégier Z2/récupération`,
      source: "fatigue",
    });
  }

  // Alertes risque blessure
  if (runInjuryRisk && (runInjuryRisk.level === "ELEVE" || runInjuryRisk.level === "CRITIQUE")) {
    alerts.push({
      severity: runInjuryRisk.level === "CRITIQUE" ? "critical" : "warning",
      message: `Risque blessure CAP ${runInjuryRisk.levelLabel} (${runInjuryRisk.score}%)`,
      source: "injuryRisk",
    });
  }

  // Alerte cross-validation MLSS run (Modèle C) — silencieuse sauf si critique
  if (runMLSS?.crossValidation && runMLSS.crossValidation.severity === "critical") {
    alerts.push({
      severity: "warning",
      message: `Incohérence VLamax/CE/seuil run (Δ${runMLSS.crossValidation.deltaPct > 0 ? "+" : ""}${runMLSS.crossValidation.deltaPct}%) — recalibrer`,
      source: "runMLSS",
    });
  }

  // Alertes readiness
  if (readiness.flags.dataIncomplete) {
    alerts.push({
      severity: "info",
      message: "Données incomplètes — diagnostic à interpréter avec prudence",
      source: "readiness",
    });
  }

  // Points forts
  const strengths: string[] = [];
  for (const gap of limiter.gapAnalysis) {
    if (gap.status === "optimal") {
      strengths.push(`${gap.metric} au niveau cible`);
    }
  }

  // Priorités L1/L2 — source unique : moteur unifié (hybride dominant + 0.4×autres)
  // R1+R2 : on ne re-dérive plus L2 localement via gapAnalysis[1] (impact brut),
  // ce qui désynchronisait la synthèse TFCL du `secondaryLever` envoyé au prompt IA
  // et utilisait un mapping métrique→catégorie local divergent (FatMax, W' incohérents).
  const L1 = {
    limiter: limiter.primaryLimiter,
    lever: limiter.primaryLever,
    label: limiter.limiterLabel,
  };

  const L2 = limiter.secondaryLimiter !== "none" && limiter.secondaryLimiter !== limiter.primaryLimiter
    ? {
        limiter: limiter.secondaryLimiter,
        lever: limiter.secondaryLever,
        label: limiter.secondaryLimiterLabel ?? LIMITER_INFO[limiter.secondaryLimiter].label,
      }
    : null;

  // Score global
  const globalScore = readiness.readiness.score;
  const globalCategory = globalScore < 50 ? "critical" as const
    : globalScore < 65 ? "developing" as const
    : globalScore < 80 ? "solid" as const
    : "ready" as const;

  const headline = generateHeadline(limiter, readiness, fatigue);

  return {
    headline,
    priorities: { L1, L2 },
    globalScore,
    globalCategory,
    alerts: alerts.slice(0, 3),
    strengths,
  };
}

function generateHeadline(
  limiter: UnifiedLimiterResult,
  readiness: PotentielV2Result,
  fatigue: FatigueEffectif
): string {
  if (fatigue.score > 75) {
    return `Fatigue critique — priorité récupération avant toute qualité`;
  }
  if (limiter.primaryLimiter === "none") {
    return `Profil équilibré — ${readiness.readiness.categoryLabel}`;
  }
  // Use limiter-specific severity instead of global readiness to avoid contradictions
  const worstGap = Math.min(...limiter.gapAnalysis.filter(g => g.status === "limiting" && canGuidePrescription(g)).map(g => g.gap));
  const severityLabel = worstGap < -15 ? "Axe prioritaire"
    : worstGap < -5 ? "À développer"
    : "Axe de progression";
  return `Limiteur principal : ${limiter.limiterLabel} — ${severityLabel}`;
}

// R1 : `mapMetricToLimiter`/`mapMetricToLever` locaux supprimés.
// La synthèse L1/L2 utilise désormais uniquement `limiter.primary*`/`limiter.secondary*`
// produits par `detectUnifiedLimiter` (source unique partagée avec planConfigBuilder).


// ═══════════════════════════════════════════════════════════════════════════════
// DATA COMPLETENESS
// ═══════════════════════════════════════════════════════════════════════════════

function computeDataCompleteness(input: DiagnosticInput): number {
  // ✅ VLamax adaptée à l'objectif : pour un runner pur, c'est vlamax_run
  // qui compte dans la complétude (pas la VLamax vélo).
  const goalVlamax = input.sportFocus === "run" ? input.vlamaxRun : input.vlamax;

  const fields: (number | null | undefined)[] = [
    input.vo2max,
    input.ftp,
    input.ftpKg,
    goalVlamax,
    input.tteObservedMin ?? input.tss7d,
    input.pmax5s,
    input.weightKg,
  ];

  if (input.sportFocus === "run" || input.sportFocus === "tri") {
    fields.push(input.vma, input.css, input.runEconomyScore);
  }
  if (input.sportFocus === "bike" || input.sportFocus === "tri") {
    fields.push(input.p30sW, input.p60sW, input.map5minW);
  }
  // En triathlon on attend AUSSI vlamax_run (scoring CAP-spécifique)
  if (input.sportFocus === "tri") {
    fields.push(input.vlamaxRun);
  }

  const present = fields.filter(f => f !== null && f !== undefined).length;
  return Math.round((present / fields.length) * 100) / 100;
}

/**
 * Run MLSS Predictor — Modèle C calibré (Nov 2026)
 * 
 * Formule fittée sur N=14 profils labo run + 3 edge cases (poids 0.3) :
 *   MLSS_pct ≈ 1 − 0.337 × VLamax − 0.0021 × (CE − 200)
 * 
 * Performance : RMSE 2.64% (vs Modèle A Mader-Heck adapté: 4.1%, Modèle B linéaire simple: 3.8%).
 * Le terme CE capture la pénalité d'un coût énergétique élevé (coureurs lourds/inefficaces)
 * sur le seuil exprimé en %VO2max.
 * 
 * Sources: Tonnessen 2015, Joyner 1991, INSCYD running whitepapers, Hauser 2014.
 * 
 * @see mem://logic/mader-alpha-calibration-n44 — équivalent bike (forme analytique différente)
 */

const RUN_K_VLAMAX = 0.337;
const RUN_K_CE = 0.0021;
const RUN_CE_REF = 200; // ml O2/kg/km, référence coureur efficient

/** Feature flag : enable Modèle C predictor (Nov 2026 calibration). */
export const USE_RUN_MLSS_PREDICTOR_V2 = true;

export interface RunMLSSPrediction {
  /** MLSS exprimé en % de VO2max (0-100) */
  mlssPct: number;
  /** Confidence du modèle [0-1] basée sur la complétude des inputs */
  confidence: number;
  /** Trace pour audit / UI */
  trace: {
    formula: string;
    vlamaxContribution: number;  // points % retirés par la VLamax
    ceContribution: number;      // points % retirés/ajoutés par le CE
    rmseExpected: number;
  };
}

/**
 * Prédit le MLSS_pct d'un coureur depuis sa VLamax run et son CE.
 * 
 * @param vlamaxRun  mmol/L/s (typique 0.25-0.65)
 * @param runningEconomy  ml O2/kg/km (typique 180-230)
 * @returns prediction ou null si inputs insuffisants
 */
export function predictRunMLSSPctFromVLaCE(
  vlamaxRun: number | null | undefined,
  runningEconomy: number | null | undefined,
): RunMLSSPrediction | null {
  if (!USE_RUN_MLSS_PREDICTOR_V2) return null;
  if (vlamaxRun == null || vlamaxRun <= 0) return null;
  if (runningEconomy == null || runningEconomy <= 0) return null;

  // Bornes physiologiques de sécurité
  const vla = Math.max(0.10, Math.min(1.20, vlamaxRun));
  const ce = Math.max(150, Math.min(280, runningEconomy));

  const vlaContrib = RUN_K_VLAMAX * vla;
  const ceContrib = RUN_K_CE * (ce - RUN_CE_REF);
  const mlssFraction = 1 - vlaContrib - ceContrib;

  // Clamp 55-95% (limite physiologique connue, MLSS coureur jamais < 55% en pratique)
  const mlssPct = Math.max(55, Math.min(95, mlssFraction * 100));

  // Confidence : pénalité si on est aux extrêmes (extrapolation)
  let confidence = 0.85;
  if (vla < 0.20 || vla > 0.80) confidence -= 0.15;
  if (ce < 175 || ce > 235) confidence -= 0.10;
  confidence = Math.max(0.50, confidence);

  return {
    mlssPct: Number(mlssPct.toFixed(1)),
    confidence: Number(confidence.toFixed(2)),
    trace: {
      formula: "MLSS_pct = 100·(1 − 0.337·VLa − 0.0021·(CE−200))",
      vlamaxContribution: Number((vlaContrib * 100).toFixed(2)),
      ceContribution: Number((ceContrib * 100).toFixed(2)),
      rmseExpected: 2.64,
    },
  };
}

/**
 * Cross-validator silencieux : compare le MLSS observé (depuis pace_threshold + VO2max)
 * au MLSS prédit par le Modèle C. Retourne une alerte si l'écart dépasse le seuil.
 * 
 * Usage : alerter le coach d'une incohérence VLamax/CE/threshold sans modifier le diagnostic.
 * 
 * @param observedMLSSPct  MLSS observé (0-100), typiquement dérivé de pace_threshold
 * @param vlamaxRun        VLamax run (mmol/L/s)
 * @param runningEconomy   CE (ml O2/kg/km)
 * @param thresholdPct     Seuil d'alerte en points % (défaut 5%)
 */
export interface RunMLSSCrossValidation {
  observed: number;
  predicted: number;
  deltaPct: number;
  isCoherent: boolean;
  severity: "ok" | "warning" | "critical";
  explanation: string;
  predictionConfidence: number;
}

export function crossValidateRunMLSS(
  observedMLSSPct: number,
  vlamaxRun: number | null | undefined,
  runningEconomy: number | null | undefined,
  thresholdPct: number = 5,
): RunMLSSCrossValidation | null {
  const prediction = predictRunMLSSPctFromVLaCE(vlamaxRun, runningEconomy);
  if (!prediction) return null;
  if (observedMLSSPct <= 0 || observedMLSSPct > 100) return null;

  const delta = observedMLSSPct - prediction.mlssPct;
  const absDelta = Math.abs(delta);

  let severity: "ok" | "warning" | "critical";
  let explanation: string;

  if (absDelta <= thresholdPct) {
    severity = "ok";
    explanation = "Cohérence VLamax/CE/seuil validée par le Modèle C.";
  } else if (absDelta <= thresholdPct * 2) {
    severity = "warning";
    explanation = delta > 0
      ? `Seuil observé ${absDelta.toFixed(1)}% au-dessus de la prédiction. VLamax sous-estimée ou CE améliorée récemment ?`
      : `Seuil observé ${absDelta.toFixed(1)}% en-dessous de la prédiction. Fatigue, VLamax sur-estimée, ou test seuil mal exécuté ?`;
  } else {
    severity = "critical";
    explanation = delta > 0
      ? `Écart majeur (+${absDelta.toFixed(1)}%) : recalibrer VLamax run ou re-tester CE.`
      : `Écart majeur (−${absDelta.toFixed(1)}%) : pace_threshold suspect, refaire test seuil.`;
  }

  return {
    observed: Number(observedMLSSPct.toFixed(1)),
    predicted: prediction.mlssPct,
    deltaPct: Number(delta.toFixed(2)),
    isCoherent: severity === "ok",
    severity,
    explanation,
    predictionConfidence: prediction.confidence,
  };
}
